(* [comment removed for export] *)
Definition dof_contD (Q : machine_state -> Prop) (pc : Z) (rax spx gp tp s0 s1 a5 a6 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word)
    (F : bvmap 5 word) (fc : bv 32) (m1 : mem) : Prop :=
  forall t0' t1' t2' a0' a1' a2' a3' a4' a7' t3' t4' t5' t6',
    evt bsegs Q (MS (mkR rax spx gp tp t0' t1' t2' s0 s1 a0' a1' a2' a3' a4' a5 a6 a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6')
                    F (Z_to_bv 64 pc) fc None m1 (seg_rom bsegs)).

(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma cl_digits : forall (k j : nat) (Q : machine_state -> Prop) rax spx gp tp t0 t1 t2 s0 s1 (v : word) a3 a4 a5 a6 a7 s3 s5 s6 s9 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (vp vq vl : Z) (vbs : list byte) (P0 P2 N1 : Z),
  (Z.to_nat vl - j = k)%nat -> (j < Z.to_nat vl)%nat ->
  bytes_at bsegs m1 vp vbs -> accessible m1 vp (Z.of_nat (length vbs)) -> mem_inv bsegs m1 ->
  vp <= vq -> 0 <= vl -> vq + vl <= vp + Z.of_nat (length vbs) -> vp + Z.of_nat (length vbs) < 2^64 -> 0 < vp ->
  (forall v' : word, dof_cont Q 0xd5f7c rax spx gp tp s0 s1 v' s3 (wz M1W) s5 s6 (wz CLMAX10) (wz 10) s9 (wz M10W) (wz ASHADOW_BASE) F fc m1) ->
  (forall v' : word, dof_contD Q 0xd5efc rax spx gp tp s0 s1 a5 a6 v' s3 (wz M1W) s5 s6 (wz CLMAX10) (wz 10) s9 (wz M10W) (wz ASHADOW_BASE) F fc m1) ->
  P0 = vq + Z.of_nat j -> P2 = vq + Z.of_nat j -> N1 = vl - Z.of_nat j ->
  evt bsegs Q (MS (mkR rax spx gp tp t0 t1 t2 s0 s1 (wz P0) (wz N1) (wz P2) a3 a4 a5 a6 a7
                       v s3 (wz M1W) s5 s6 (wz CLMAX10) (wz 10) s9 (wz M10W) (wz ASHADOW_BASE) t3 t4 t5 t6)
                  F (Z_to_bv 64 0xd5ea0) fc None m1 (seg_rom bsegs)).
